package ec.edu.scli.reservas.presentation.controller;
import ec.edu.scli.reservas.application.service.SolicitudCambioPlanificacionService; import ec.edu.scli.reservas.presentation.dto.request.*; import ec.edu.scli.reservas.presentation.dto.response.SolicitudCambioResponse; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/planificaciones-agregadas/{planId}/solicitudes-cambio") public class SolicitudCambioPlanificacionController { private final SolicitudCambioPlanificacionService service; public SolicitudCambioPlanificacionController(SolicitudCambioPlanificacionService s){service=s;} @GetMapping public List<SolicitudCambioResponse> listar(@PathVariable UUID planId){return service.listar(planId);} @PostMapping public ResponseEntity<SolicitudCambioResponse> crear(@PathVariable UUID planId,@Valid @RequestBody CrearSolicitudCambioRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.crear(planId,r));} @PostMapping("/{id}/aprobar") public SolicitudCambioResponse aprobar(@PathVariable UUID planId,@PathVariable UUID id,@RequestBody(required=false) ResolverSolicitudCambioRequest r){return service.aprobar(id,r==null?null:r.observacion());} @PostMapping("/{id}/rechazar") public SolicitudCambioResponse rechazar(@PathVariable UUID planId,@PathVariable UUID id,@RequestBody ResolverSolicitudCambioRequest r){return service.rechazar(id,r.observacion());} }
